    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por el art. 63, numeral 1, del Decreto No. 102-2018, Ley Especial de Adopciones (La Gaceta No. 34,841 del 10 de enero de 2019), literal a): Capítulo VI del Título IV. Dictamen del CLO (D5, 2026-11-24)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CF_OLA5.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA5')
  WHERE ingest_batch = 'OLA5_CF_2023_01' AND id IN ('OLA5_CF_2023_01:CODIGO_FAMILIA:175-A');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA5_CF_2023_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
