  IF n <> 298 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 298)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA5_CF_2023_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 1 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 1)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA5_CF_2023_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 80 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 80)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA5_CF_2023_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
