  WHERE b.metadata->>'norm_id' = 'HN_CODIGO_FAMILIA' AND b.id LIKE 'v2familia:mayalex_normativos:%' AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 373 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 373)', n; END IF;
